cd /tmp && cat > probe.py << 'PYEOF'
import hashlib, hmac, base64, json, subprocess

B="/workspace/artifacts/target/jwt-verify"
SECRET="s3cr3t-probe-key"

def b64u(b):
    if isinstance(b,str): b=b.encode()
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()

def make(payload, header=None):
    h=header or {"alg":"HS256","typ":"JWT"}
    seg=b64u(json.dumps(h,separators=(",",":")).encode())+"."+b64u(json.dumps(payload,separators=(",",":")).encode())
    sig=hmac.new(SECRET.encode(),seg.encode(),hashlib.sha256).digest()
    return seg+"."+b64u(sig)

def run(tok):
    r=subprocess.run([B,"--token",tok,"--key",SECRET],capture_output=True,text=True,timeout=30)
    return r.stdout.strip()

# baseline empty
tests={
 "empty":{},
 "sub":{"sub":"user1"},
 "iss_str":{"iss":"someissuer"},
 "aud_str":{"aud":"someaud"},
 "exp_future":{"exp":9999999999},
 "exp_past":{"exp":1},
 "nbf_future":{"nbf":9999999999},
 "iat":{"iat":1000},
 "role":{"role":"admin"},
 "scope":{"scope":"read"},
}
for name,p in tests.items():
    print(name, "=>", run(make(p)))
PYEOF
python3 probe.py

